import java.util.HashMap;
import java.util.Map;

public class HashMapDemo {
    public static void main(String[] args) {
        // 预估 1000 个元素：容量 = 1000 / 0.75 + 1，避免多次扩容
        Map<String, Integer> map = new HashMap<>((int) (1000 / 0.75f) + 1);
        map.put("a", 1);
        map.merge("a", 1, Integer::sum);      // a -> 2
        map.computeIfAbsent("b", k -> 10);
        System.out.println(map);              // {a=2, b=10}

        int h = "a".hashCode();
        int hash = h ^ (h >>> 16);
        System.out.println("index in 16 = " + ((16 - 1) & hash));
    }
}

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.LongAdder;

public class PvCounter {
    private final ConcurrentHashMap<String, LongAdder> pv = new ConcurrentHashMap<>();

    public void hit(String url) {
        // computeIfAbsent 是原子的；避免 get-then-put 的竞态
        pv.computeIfAbsent(url, k -> new LongAdder()).increment();
    }

    public long count(String url) {
        LongAdder a = pv.get(url);
        return a == null ? 0 : a.sum();
    }
}

import java.util.HashMap;
import java.util.Map;

public class ResizeDemo {
    public static void main(String[] args) {
        int expected = 1000;
        Map<String, Integer> m1 = new HashMap<>((int) (expected / 0.75f) + 1); // 1334 → 实际容量 2048
        Map<String, Integer> m2 = HashMap.newHashMap(expected);                // JDK 19+ 推荐写法
        for (int i = 0; i < expected; i++) { m1.put("k" + i, i); m2.put("k" + i, i); }

        // 默认构造：16 → 32 → 64 → ... → 2048，经历 7 次扩容
        Map<String, Integer> m3 = new HashMap<>();
        for (int i = 0; i < expected; i++) m3.put("k" + i, i);
    }
}

